CREATE OR REPLACE FUNCTION public.disconnect_current_accountant(p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID;
    v_org_id UUID;
    v_link_id UUID;
    v_firm_id UUID;
    v_rows_affected INT;
BEGIN
    -- Identify User
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz erişim. Lütfen giriş yapın.');
    END IF;

    -- Find User's Organization
    SELECT organization_id INTO v_org_id
    FROM public.organization_members
    WHERE user_id = v_user_id
    LIMIT 1;

    IF v_org_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Herhangi bir organizasyona bağlı değilsiniz.');
    END IF;

    -- Find Active Link
    SELECT id, accounting_firm_id INTO v_link_id, v_firm_id
    FROM public.accountant_taxpayer_links
    WHERE taxpayer_organization_id = v_org_id AND status = 'active'
    LIMIT 1;

    IF v_link_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'ACTIVE_CONNECTION_NOT_FOUND', 'message', 'Kesilecek aktif bir bağlantı bulunamadı.');
    END IF;

    -- Disconnect
    UPDATE public.accountant_taxpayer_links
    SET 
        status = 'disconnected',
        disconnected_at = NOW(),
        disconnected_by_user_id = v_user_id,
        disconnect_source = 'flow',
        disconnect_reason = p_reason,
        updated_at = NOW()
    WHERE id = v_link_id AND status = 'active';

    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;

    IF v_rows_affected = 0 THEN
         RETURN jsonb_build_object('success', false, 'error', 'Bağlantı kesme işlemi başarısız oldu (Zaten kesilmiş olabilir).');
    END IF;

    -- Write Audit Event
    INSERT INTO public.accountant_connection_events (
        event_type, actor_user_id, accounting_firm_id, taxpayer_organization_id, 
        previous_status, new_status, reason, source
    ) VALUES (
        'connection.disconnected_by_taxpayer',
        v_user_id,
        v_firm_id,
        v_org_id,
        'active',
        'disconnected',
        p_reason,
        'flow'
    );

    RETURN jsonb_build_object('success', true, 'message', 'Bağlantı başarıyla kesildi.');
END;
$function$

CREATE OR REPLACE FUNCTION public.get_financial_report_summary(p_target_month date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_profile_id uuid;
  v_income_minor bigint := 0;
  v_expense_minor bigint := 0;
  v_receivable_minor bigint := 0;
  v_payable_minor bigint := 0;
  v_net_minor bigint := 0;
  v_start_date date;
  v_end_date date;
  v_currency text := 'TRY';
BEGIN
  -- Güvenlik: Aktif profili/organizasyonu çöz
  v_profile_id := auth.uid();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Ana para birimini bul
  SELECT COALESCE(default_currency, 'TRY') INTO v_currency
  FROM public.profiles
  WHERE id = v_profile_id;

  -- Hedef ayın başını ve sonunu hesapla
  v_start_date := date_trunc('month', p_target_month)::date;
  v_end_date := (v_start_date + interval '1 month' - interval '1 day')::date;

  -- 1. Gelir/Gider: Seçili ay içindeki confirmed işlemler
  SELECT 
    COALESCE(SUM(CASE WHEN t.type = 'income' THEN t.amount_minor ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN t.type = 'expense' THEN t.amount_minor ELSE 0 END), 0)
  INTO v_income_minor, v_expense_minor
  FROM public.transactions t
  WHERE t.profile_id = v_profile_id 
    AND t.date >= v_start_date AND t.date <= v_end_date
    AND t.transaction_status = 'confirmed';

  v_net_minor := v_income_minor - v_expense_minor;

  -- 2. Tahsil Edilecek / Ödenecek: remaining_amount_minor > 0 olan confirmed işlemler
  SELECT 
    COALESCE(SUM(CASE WHEN t.type = 'income' THEN COALESCE(t.remaining_amount_minor, t.amount_minor) ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN t.type = 'expense' THEN COALESCE(t.remaining_amount_minor, t.amount_minor) ELSE 0 END), 0)
  INTO v_receivable_minor, v_payable_minor
  FROM public.transactions t
  WHERE t.profile_id = v_profile_id 
    AND t.transaction_status = 'confirmed'
    AND t.payment_status != 'paid';

  RETURN json_build_object(
    'month', to_char(p_target_month, 'YYYY-MM'),
    'currency', v_currency,
    'incomeMinor', v_income_minor,
    'expenseMinor', v_expense_minor,
    'netMinor', v_net_minor,
    'receivableMinor', v_receivable_minor,
    'payableMinor', v_payable_minor
  );
END;
$function$
